service-call.in-map:
{emailAccountId:emailAccountId, accountName:accountName,
                syncWindowDays:(syncWindowDays == 'all' ? '' : (syncWindowDays ?? null)), recordFilingEnumId:recordFilingEnumId,
                accountKindEnumId:(accountKindEnumId || null)}

actions.script:
if (!memberUserIds) { ec.message.addValidationError(null, 'memberUserIds', null, ec.l10n.localize('Choose who to add'), null); return }
const out = ec.service.sync().name('org.moqui.comms.MailSettingsServices.save#AccountOptions').parameters({emailAccountId: emailAccountId,
    memberUserIds: memberUserIds, memberPermissionEnumId: memberPermissionEnumId || 'EapSend'}).call()
if (!ec.message.hasError() && out?.addedMemberCount) ec.message.addMessage(ec.resource.expand(out.addedMemberCount == 1 ? 'Added 1 person' : 'Added ${n} people', '',
    {n: out.addedMemberCount}), 'success')

if (!mailFile) { ec.message.addValidationError(null, 'mailFile', null, ec.l10n.localize('Choose a .eml or .mbox file'), null); return }
if (!emailFolderId) { ec.message.addValidationError(null, 'emailFolderId', null, ec.l10n.localize('Choose the folder'), null); return }
const out = ec.service.sync().name('org.moqui.impl.EmailClientServices.import#EmailMessages').parameters({emailFolderId: emailFolderId, file: mailFile}).call()
if (ec.message.hasError()) return
const text = ec.resource.expand('Imported ${imported}; ${duplicates} already here; ${failed} could not be read', '', {imported: out?.importedCount || 0,
    duplicates: out?.duplicateCount || 0, failed: out?.failedCount || 0})
ec.message.addMessage(text, out?.failedCount ? 'warning' : 'success')
